import { Prisma } from "@/generated/prisma/client";
/**
 * [P12B.5] تكلفة البضاعة المباعة لبيع نقطة بيع (BRD §7.2 سطر 5).
 *
 * الحدّ الذي يغلقه هذا الملف (contract KL-5): «لا تُلتقط تكلفة عند الصرف، فربح
 * المبيعات من على الطاولة خيال». البيع كان يعرف سعره ولا يعرف كلفته إطلاقًا.
 *
 * المصدر هو دفتر حركات المخزون لا سطور البيع — للسبب نفسه الذي جعل الإرجاع يقرأ
 * الدفتر ([P12B.2]): صنف متتبَّع بالدُفعات يُصرف FEFO وقد تُقسَّم كميته على دفعات
 * تكلفتها مختلفة. `valuationRate` المحفوظ على كل حركة صرف هو متوسط التكلفة وقتها،
 * وهو تحديدًا الرقم الذي يجب أن يُقيَّد به. اشتقاقه لاحقًا من متوسط اليوم يعطي رقمًا
 * آخر كلّما تحرّك المتوسط بعد البيع.
 *
 * ولأن الحركات المعاكسة ([P12B.2]) تحمل `valuationRate` نفسه، فالمبلغ الذي يُعكَس
 * عند الإرجاع هو المبلغ الذي رُحِّل — يعود أثر التكلفة إلى صفر بلا فرق متبقٍّ.
 */
type Tx = Prisma.TransactionClient;
/**
 * @returns تكلفة الأصناف المصروفة لهذا البيع بعملة الدفتر. صفرٌ بيعٌ لم يمسّ المخزون
 * (دورة، أو صنف بلا ربط) — وهي حالة سليمة لا خطأ: بيع بلا بضاعة لا تكلفة بضاعة له.
 */
export declare function computeSaleCogs(tx: Tx, clinicId: string, saleId: string): Promise<Prisma.Decimal>;
export {};
